CREATE DATABASE IF NOT EXISTS invoiceflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE invoiceflow;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clients(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,phone VARCHAR(40),tax_id VARCHAR(40),address VARCHAR(255),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_clients_user FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invoices(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,client_id INT NOT NULL,number VARCHAR(30) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL,amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL DEFAULT 'COP',due_date DATE NOT NULL,status ENUM('DRAFT','SENT','PAID','OVERDUE','CANCELLED') NOT NULL DEFAULT 'DRAFT',stripe_session_id VARCHAR(255),payment_url TEXT,paid_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_invoices_user FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,CONSTRAINT fk_invoices_client FOREIGN KEY(client_id)REFERENCES clients(id)ON DELETE RESTRICT);
